/* ---------- Task table ---------- */
.ttx{overflow:hidden;position:relative}
.ttx-sc{overflow-x:auto}
.ttx-t{width:100%;border-collapse:collapse;font-size:13px;min-width:560px}
.ttx-t th{text-align:left;font-weight:500;font-size:12px;color:var(--muted);padding:10px 8px;border-bottom:1px solid var(--line);white-space:nowrap}
.ttx-t th.ck,.ttx-t td.ck{width:36px;padding-left:14px}
.ttx-t th.r,.ttx-t td.r{text-align:right}
.ttx-t th:last-child,.ttx-t td:last-child{padding-right:14px}
.ttx-s{display:inline-flex;align-items:center;gap:4px;color:inherit;font:inherit}
.ttx-s:hover{color:var(--fg)}
.ttx-s .ar{opacity:0;transition:opacity .2s,transform .3s var(--ease);display:grid}
.ttx-s.on{color:var(--fg)}.ttx-s.on .ar{opacity:1}.ttx-s.on.desc .ar{transform:rotate(180deg)}
.ttx-t td{padding:9px 8px;border-bottom:1px solid var(--line);white-space:nowrap}
.ttx-t tr:last-child td{border-bottom:0}
.ttx-t tbody tr{transition:background .2s}
.ttx-t tbody tr:hover{background:var(--row)}
.ttx-t tbody tr.sel{background:var(--sel)}
.ttx-t .nm{font-weight:500}
.ttx-t .ag{display:flex;align-items:center;gap:7px;color:var(--fg2)}
.ttx-t .ag .av{width:20px;height:20px;font-size:9.5px}
.ttx-t td.num{color:var(--fg2)}
.ttx-cb{width:16px;height:16px;border-radius:5px;box-shadow:inset 0 0 0 1.5px var(--faint);display:grid;place-items:center;color:#fff;transition:background .25s,box-shadow .25s}
.ttx-cb[aria-checked="true"],.ttx-cb[aria-checked="mixed"]{background:var(--accent);box-shadow:none}
.ttx-cb svg{width:11px;height:11px}
.ttx-st{display:inline-flex;align-items:center;gap:6px;font-size:12.5px}
.ttx-bar{position:absolute;left:50%;bottom:12px;display:flex;align-items:center;gap:2px;padding:4px 4px 4px 14px;border-radius:999px;background:var(--ink);color:var(--on-ink);box-shadow:var(--shadow-pop);transform:translate(-50%,16px) scale(.96);opacity:0;filter:blur(4px);pointer-events:none;transition:transform .45s var(--ease),opacity .3s,filter .3s;white-space:nowrap}
.ttx-bar.show{transform:translate(-50%,0);opacity:1;filter:none;pointer-events:auto}
.ttx-bar .pill.ghost{color:inherit;opacity:.85}.ttx-bar .pill.ghost:hover{background:color-mix(in srgb,var(--on-ink) 14%,transparent);opacity:1}
.ttx-n{font-size:12.5px;margin-right:8px}
.ttx-t tbody{position:relative}
.ttx-pad td{height:48px;border:0}
@container (max-width:560px){.ttx-t{min-width:0}.ttx-t th:nth-child(6),.ttx-t td:nth-child(6){display:none}.ttx-t th:nth-child(5),.ttx-t td:nth-child(5){padding-right:14px}}

DM.def('task-table', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{pause}', I('pause','xs')).replace('{refresh}', I('refresh','xs')).replace('{x}', I('x','xs'));
  const ST = { run:['Running','<span class="spin" style="width:12px;height:12px"></span>'], done:['Done',`<span style="color:var(--ok);display:grid">${I('ok','xs')}</span>`], fail:['Failed',`<span style="color:var(--bad);display:grid">${I('alert','xs')}</span>`], wait:['Queued','<span class="dot" style="color:var(--faint)"></span>'], pause:['Paused',`<span class="muted" style="display:grid">${I('pause','xs')}</span>`] };
  let T = [
    ['Audit pricing contrast','run','Design','DS','var(--pb)',0.42,2],
    ['Export tokens to CSS','done','Code','CO','var(--pm)',0.18,14],
    ['Sync Figma frames','fail','Design','DS','var(--pb)',0.07,26],
    ['Draft launch email','wait','Writer','WR','var(--pl)',0,31],
    ['Compare checkout flows','done','Research','RE','var(--pt)',0.66,48],
    ['Rename layers in Hero','run','Design','DS','var(--pb)',0.11,5]
  ].map((x, i) => ({ id:i, n:x[0], s:x[1], a:x[2], ai:x[3], ac:x[4], cost:x[5], up:x[6], sel:false }));
  const tb = $('tbody', r), all = $('.ttx-all', r), bar = $('.ttx-bar', r);
  let key = 4, desc = false;
  $$('.ttx-s', r).forEach(b => b.insertAdjacentHTML('beforeend', `<span class="ar">${I('chev-u','xs')}</span>`));
  const fields = [t => t.n, t => ['run','fail','wait','pause','done'].indexOf(t.s), t => t.a, t => t.cost, t => t.up];
  function paint(anim){
    const f = fields[key]; const rows = [...T].sort((a, b) => { const x = f(a), y = f(b); return (x > y ? 1 : x < y ? -1 : 0) * (desc ? -1 : 1); });
    tb.innerHTML = rows.map(t => `<tr class="${t.sel ? 'sel' : ''}" data-id="${t.id}"><td class="ck"><button class="ttx-cb" role="checkbox" aria-checked="${t.sel}" aria-label="Select ${t.n}">${t.sel ? I('check','xs') : ''}</button></td><td class="nm">${t.n}</td><td><span class="ttx-st">${ST[t.s][1]}${ST[t.s][0]}</span></td><td><span class="ag">${AV(t.ai, t.ac)}${t.a}</span></td><td class="r num">$${t.cost.toFixed(2)}</td><td class="r num muted">${t.up}m ago</td></tr>`).join('') + '<tr class="ttx-pad"><td colspan="6"></td></tr>';
    if (anim) stagger($$('tr:not(.ttx-pad)', tb), 30);
    $$('.ttx-s', r).forEach(b => { b.classList.toggle('on', +b.dataset.k === key); b.classList.toggle('desc', desc); });
    $$('tbody tr[data-id]', r).forEach(tr => tr.onclick = () => { const t = T[+tr.dataset.id]; t.sel = !t.sel; paint(); });
    const n = T.filter(t => t.sel).length; all.setAttribute('aria-checked', n === 0 ? 'false' : n === T.length ? 'true' : 'mixed'); all.innerHTML = n ? I(n === T.length ? 'check' : 'minus','xs') : '';
    bar.classList.toggle('show', n > 0); if (n) $('.ttx-n', bar).textContent = n + ' selected';
  }
  $$('.ttx-s', r).forEach(b => b.onclick = () => { const k = +b.dataset.k; if (k === key) desc = !desc; else { key = k; desc = false; } paint(true); });
  all.onclick = () => { const on = all.getAttribute('aria-checked') !== 'true'; T.forEach(t => t.sel = on); paint(); };
  $$('.ttx-bar [data-a]', r).forEach(b => b.onclick = () => { const a = b.dataset.a;
    T.forEach(t => { if (!t.sel) return; if (a === 'pause' && (t.s === 'run' || t.s === 'wait')) t.s = 'pause'; if (a === 'retry' && (t.s === 'fail' || t.s === 'pause')) { t.s = 'run'; t.up = 0; } t.sel = false; });
    if (a === 'cancel') T = T.filter(t => !$(`tr[data-id="${t.id}"]`, tb)?.classList.contains('sel')).map((t, i) => ({ ...t, id:i }));
    paint(true); });
  paint(true);
  c.later(1600, () => { if (!T.some(t => t.sel)) { T[2].sel = true; T[5].sel = true; paint(); } });
});
